INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM203AATV', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 2, 'mcq', E'A locksmith charges a flat dispatch fee of 46 dollars plus 23 dollars for each hour of labor. If the total charge for a job was 184 dollars, how many hours did the locksmith work?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$7$"},{"key":"C","text":"$8$"},{"key":"D","text":"$10$"}]$lyceon_json$::jsonb, 'A', NULL, E'Set up the equation $23h + 46 = 184$, where $h$ is hours worked. Subtracting $46$ from both sides gives $23h = 138$, and dividing by $23$ yields $h = 6$. The value $7$ results from a computational error in the final division. The value $8$ comes from dividing the total $184$ by $23$ without first subtracting the dispatch fee. The value $10$ results from incorrectly adding the fee to the total ($184 + 46 = 230$) before dividing by $23$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM20A9WV1', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 1, 'mcq', E'The function $f(x) = (x - 11)^2 + 5$ has a minimum value. What is the minimum value of $f$?', NULL, $lyceon_json$[{"key":"A","text":"$-11$"},{"key":"B","text":"$5$"},{"key":"C","text":"$11$"},{"key":"D","text":"$-5$"}]$lyceon_json$::jsonb, 'B', NULL, E'The function is written in vertex form $f(x) = (x - h)^2 + k$, where the vertex is $(h, k) = (11, 5)$. Because the coefficient of $(x - 11)^2$ is positive, the parabola opens upward and the vertex is the minimum point. The minimum value of the function is the $y$-coordinate of the vertex, which is $5$. Choosing $-11$ confuses the horizontal shift with the minimum value and applies the wrong sign. Choosing $11$ takes the $x$-coordinate of the vertex instead of the $y$-coordinate. Choosing $-5$ applies a sign error to the vertical shift.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM224BBJK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 2, 'mcq', E'A bakery uses 7 cups of a specialty flour blend to make 4 loaves of artisan bread. The bakery needs to make 52 loaves for a catering order. If the flour blend comes in bags of 5 cups each, how many bags must the bakery purchase?', NULL, $lyceon_json$[{"key":"A","text":"$18$"},{"key":"B","text":"$19$"},{"key":"C","text":"$21$"},{"key":"D","text":"$73$"}]$lyceon_json$::jsonb, 'B', NULL, E'First, find the total flour needed: $\\frac{7}{4} \\times 52 = 91$ cups. Then divide by the bag size: $91 \\div 5 = 18.2$. Since partial bags cannot be purchased, the bakery must buy $19$ bags. The value 18 comes from correctly computing 91 cups but rounding down $18.2$ instead of rounding up, which would leave the bakery short of flour. The value 21 results from an arithmetic slip using 8 cups instead of 7, giving $\\frac{8}{4} \\times 52 = 104$ cups and $104 \\div 5 = 20.8 \\to 21$ bags. The value 73 results from multiplying $52 \\times 7 = 364$ without dividing by 4, then computing $\\frac{364}{5} = 72.8 \\to 73$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM238JIJ9', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 2, 'grid_in', E'A line passes through the points $(3, 11)$ and $(7, 31)$. What is the $y$-intercept of this line?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '-4', ARRAY['-4'], E'First find the slope: $m = \\frac{31 - 11}{7 - 3} = \\frac{20}{4} = 5$. Using point-slope form with $(3, 11)$: $y - 11 = 5(x - 3)$, which gives $y = 5x - 15 + 11 = 5x - 4$. The $y$-intercept is $-4$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM241FAK9', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 3, 'mcq', E'If $\\frac{4(3x - 2)}{5} - \\frac{x + 7}{2} = \\frac{3}{5}$, what is the value of $6x - 1$?', NULL, $lyceon_json$[{"key":"A","text":"$3$"},{"key":"B","text":"$11$"},{"key":"C","text":"$17$"},{"key":"D","text":"$19$"}]$lyceon_json$::jsonb, 'C', NULL, E'Multiply every term by $10$ (the LCD of $5$, $2$, and $5$) to clear fractions: $8(3x - 2) - 5(x + 7) = 6$. Distributing gives $24x - 16 - 5x - 35 = 6$, which simplifies to $19x - 51 = 6$. Adding $51$ yields $19x = 57$, so $x = 3$. The question asks for $6x - 1 = 6(3) - 1 = 17$. The value $3$ is the result of finding $x$ but not substituting into $6x - 1$. The value $11$ arises from an error in clearing fractions, such as using an incorrect LCD. The value $19$ comes from computing $6(3) + 1$ instead of $6(3) - 1$.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
