INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM25WARUB', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 1, 'mcq', E'Which of the following best describes all values of $x$ that satisfy the inequality $8x + 13 \\leq 77$?', NULL, $lyceon_json$[{"key":"A","text":"$x \\leq 8$"},{"key":"B","text":"$x \\geq 8$"},{"key":"C","text":"$x \\leq 64$"},{"key":"D","text":"$x \\leq \\frac{77}{8}$"}]$lyceon_json$::jsonb, 'A', NULL, E'Subtracting $13$ from both sides gives $8x \\leq 64$. Dividing both sides by $8$ yields $x \\leq 8$. The distractor $x \\geq 8$ reverses the inequality direction, which is incorrect because dividing by a positive number preserves the direction. The distractor $x \\leq 64$ stops after subtracting $13$ without dividing by $8$. The distractor $x \\leq \\frac{77}{8}$ divides $77$ by $8$ without first subtracting $13$, applying operations in the wrong order.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26ECNGX', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 3, 'mcq', E'Line $p$ has the equation $3x - 4y = 24$. Line $q$ is perpendicular to line $p$ and passes through the point $(6, 4)$. At what value of $x$ does line $q$ cross the $x$-axis?', NULL, $lyceon_json$[{"key":"A","text":"$-9$"},{"key":"B","text":"$3$"},{"key":"C","text":"$6$"},{"key":"D","text":"$9$"}]$lyceon_json$::jsonb, 'D', NULL, E'Rewrite line $p$ in slope-intercept form: $y = \\frac{3}{4}x - 6$, so its slope is $\\frac{3}{4}$. A line perpendicular to it has slope $-\\frac{4}{3}$. Using point-slope form with $(6, 4)$: $y - 4 = -\\frac{4}{3}(x - 6)$, giving $y = -\\frac{4}{3}x + 12$. Setting $y = 0$: $\\frac{4}{3}x = 12$, so $x = 9$. The value $-9$ results from a sign error when computing the perpendicular slope or solving the final equation. The value $3$ comes from using the positive reciprocal slope $\\frac{4}{3}$ instead of $-\\frac{4}{3}$, yielding $y = \\frac{4}{3}x - 4$ and $x = 3$. The value $6$ mistakes the $x$-coordinate of the given point for the $x$-intercept.', $lyceon_json${"D":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"sign_error"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 110, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM26M2N29', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 3, 'grid_in', E'A store increases the price of an item by $30\\%$ and later decreases the new price by $20\\%$. If the final price of the item is 62.40 dollars, what was the original price, in dollars, of the item?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '60', ARRAY['60'], E'Let the original price be $p$. After a $30\\%$ increase the price becomes $1.30p$. After a $20\\%$ decrease applied to $1.30p$, the price becomes $1.30p \\times 0.80 = 1.04p$. Setting $1.04p = 62.40$ gives $p = \\frac{62.40}{1.04} = 60$. A common error is to assume the $30\\%$ increase and $20\\%$ decrease cancel to a net $10\\%$ increase, yielding $\\frac{62.40}{1.10} \\approx 56.73$. Another error is to apply the inverse operations sequentially on the final price — dividing by $0.80$ then by $1.30$ — which actually yields the same correct answer, but students sometimes mistakenly add and subtract instead: $62.40 + 20\\% - 30\\%$, producing an incorrect result.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM274JS3Y', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 3, 'mcq', E'The mean of a dataset of 15 values is 42. When three additional values are added to the dataset, the new mean of all 18 values is 45. If two of the three added values are 53 and 61, what is the third added value?', NULL, $lyceon_json$[{"key":"A","text":"$21$"},{"key":"B","text":"$56$"},{"key":"C","text":"$66$"},{"key":"D","text":"$180$"}]$lyceon_json$::jsonb, 'C', NULL, E'The original sum is $15 \\times 42 = 630$. The new sum of all 18 values is $18 \\times 45 = 810$. Therefore the sum of the three added values is $810 - 630 = 180$, and the third value is $180 - 53 - 61 = 66$. The value 21 results from incorrectly assuming the three added values must average to the new mean of 45, giving a sum of $3 \\times 45 = 135$, so $135 - 53 - 61 = 21$. The value 56 results from an arithmetic slip where 53 is misread as 63, giving $180 - 63 - 61 = 56$. The value 180 results from finding the sum of the three added values ($810 - 630 = 180$) but stopping there without subtracting the two known values.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM27DC8WR', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 1, 'mcq', E'Which of the following expressions is equivalent to $(5x^2 - 13x + 4) - (3x^2 + 2x - 17)$?', NULL, $lyceon_json$[{"key":"A","text":"$2x^2 - 15x + 21$"},{"key":"B","text":"$2x^2 - 11x - 13$"},{"key":"C","text":"$8x^2 - 15x + 21$"},{"key":"D","text":"$2x^2 - 15x - 13$"}]$lyceon_json$::jsonb, 'A', NULL, E'Distributing the negative sign across the second group gives $5x^2 - 13x + 4 - 3x^2 - 2x + 17$. Combining like terms: $5x^2 - 3x^2 = 2x^2$, $-13x - 2x = -15x$, and $4 + 17 = 21$. The result is $2x^2 - 15x + 21$. The distractor $2x^2 - 11x - 13$ results from failing to distribute the negative sign to the $-17$ term, keeping it as $-17$ instead of $+17$. The distractor $8x^2 - 15x + 21$ comes from adding the $x^2$ coefficients instead of subtracting. The distractor $2x^2 - 15x - 13$ results from both subtracting the $x^2$ terms correctly and distributing the negative sign to $2x$ but not to $-17$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM284B7H3', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 1, 'grid_in', E'$$\\begin{cases} 3x + 2y = 19 \\\\ x - y = 3 \\end{cases}$$
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM28EX3ZP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 3, 'mcq', E'The equation of a circle in the $xy$-plane is $x^2 + y^2 - 14x + 10y + 37 = 0$. A chord of this circle has its midpoint at $(9, -3)$. What is the length of the chord?', NULL, $lyceon_json$[{"key":"A","text":"$\\sqrt{29}$"},{"key":"B","text":"$2\\sqrt{29}$"},{"key":"C","text":"$2\\sqrt{37}$"},{"key":"D","text":"$2\\sqrt{45}$"}]$lyceon_json$::jsonb, 'B', NULL, E'Completing the square: $(x^2 - 14x + 49) + (y^2 + 10y + 25) = -37 + 49 + 25 = 37$, so the equation becomes $(x - 7)^2 + (y + 5)^2 = 37$. The center is $(7, -5)$ and $r^2 = 37$. The distance from the center to the chord''s midpoint $(9, -3)$ is $d = \\sqrt{(9 - 7)^2 + (-3 + 5)^2} = \\sqrt{4 + 4} = 2\\sqrt{2}$, so $d^2 = 8$. The perpendicular from the center to a chord bisects it, so half the chord length is $\\sqrt{r^2 - d^2} = \\sqrt{37 - 8} = \\sqrt{29}$. The full chord length is $2\\sqrt{29}$. The value $\\sqrt{29}$ is only half the chord, the result of stopping before doubling. The value $2\\sqrt{37}$ treats the chord as a diameter ($2r = 2\\sqrt{37}$), ignoring the midpoint offset. The value $2\\sqrt{45}$ results from adding $r^2 + d^2$ instead of subtracting, computing $\\sqrt{37 + 8} = \\sqrt{45}$ and doubling.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29CS3XV', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 1, 'mcq', E'In triangle $PQR$, the measure of angle $P$ is $53°$ and the measure of angle $Q$ is $71°$. What is the measure, in degrees, of angle $R$?', NULL, $lyceon_json$[{"key":"A","text":"$46$"},{"key":"B","text":"$56$"},{"key":"C","text":"$124$"},{"key":"D","text":"$127$"}]$lyceon_json$::jsonb, 'B', NULL, E'The sum of angles in a triangle is $180°$, so angle $R = 180 - 53 - 71 = 56°$. The value $46$ results from an arithmetic slip in adding $53 + 71$ as $134$ instead of $124$, then computing $180 - 134 = 46$. The value $124$ comes from adding the two given angles ($53 + 71 = 124$) and mistaking their sum for the missing angle. The value $127$ comes from subtracting only one angle ($180 - 53 = 127$), neglecting to subtract the second angle.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM29N61NV', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 3, 'mcq', E'In triangle $ABC$, point $D$ lies on side $\\overline{BC}$ such that $\\overline{AD}$ bisects angle $A$. If the measure of angle $B$ is $43°$ and the measure of angle $C$ is $59°$, what is the measure, in degrees, of angle $ADC$?', NULL, $lyceon_json$[{"key":"A","text":"$72$"},{"key":"B","text":"$78$"},{"key":"C","text":"$82$"},{"key":"D","text":"$98$"}]$lyceon_json$::jsonb, 'C', NULL, E'First, angle $A = 180 - 43 - 59 = 78°$. Since $\\overline{AD}$ bisects angle $A$, angle $DAC = \\frac{78}{2} = 39°$. In triangle $ADC$, the angle sum gives angle $ADC = 180 - 39 - 59 = 82°$. The value $72$ results from an arithmetic slip in halving angle $A$: computing $\\frac{78}{2}$ as $49$ instead of $39$, leading to $180 - 49 - 59 = 72$. The value $78$ comes from finding angle $A$ but stopping there without applying the bisector. The value $98$ is the measure of angle $ADB$ (the supplement of $82°$), obtained by a student who solves in triangle $ABD$ but reports the wrong angle at vertex $D$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2A3MGOO', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 3, 'grid_in', E'If $-4 < \\frac{3x - 11}{7} \\leq 5$, what is the greatest integer value of $x$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '15', ARRAY['15'], E'Multiply all three parts of the compound inequality by $7$: $-28 < 3x - 11 \\leq 35$. Add $11$ to each part: $-17 < 3x \\leq 46$. Divide each part by $3$: $-\\frac{17}{3} < x \\leq \\frac{46}{3}$. Since $\\frac{46}{3} \\approx 15.33$, the inequality states $x \\leq 15.33$. The greatest integer satisfying this is $15$. A common error is rounding $\\frac{46}{3}$ up to $16$, which violates the $\\leq$ constraint. Another error is treating the left bound as $\\leq$ instead of strict $<$, which does not affect the maximum but reflects a misunderstanding of the compound structure.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2AHPHXI', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 3, 'mcq', E'What are all solutions to $\\sqrt{5x + 11} = x + 1$?', NULL, $lyceon_json$[{"key":"A","text":"$x = -2$ only"},{"key":"B","text":"$x = 5$ only"},{"key":"C","text":"$x = -2$ and $x = 5$"},{"key":"D","text":"$x = 3$ only"}]$lyceon_json$::jsonb, 'B', NULL, E'Squaring both sides gives $5x + 11 = x^2 + 2x + 1$, which rearranges to $x^2 - 3x - 10 = 0$. Factoring: $(x - 5)(x + 2) = 0$, so $x = 5$ or $x = -2$. Both candidates must be checked in the original equation. For $x = 5$: $\\sqrt{5(5) + 11} = \\sqrt{36} = 6$ and $5 + 1 = 6$, so $x = 5$ is valid. For $x = -2$: $\\sqrt{5(-2) + 11} = \\sqrt{1} = 1$ but $-2 + 1 = -1$, so $x = -2$ is extraneous. Choosing $x = -2$ only reflects taking the extraneous root without verification. Choosing both solutions ignores the need to check for extraneous solutions when squaring. Choosing $x = 3$ results from an arithmetic error during factoring.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2C4KEQK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 3, 'grid_in', E'A jar contains tiles labeled with the integers from 1 through 31 inclusive. One tile is drawn at random. Let event $A$ be that the number on the tile is a multiple of 7, and let event $B$ be that the number on the tile is odd. What is the value of $P(A \\mid B) + P(B \\mid A)$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '5/8', ARRAY['5/8', '0.625', '.625'], E'The multiples of 7 from 1 to 31 are 7, 14, 21, and 28, so $|A| = 4$. The odd numbers from 1 to 31 are $1, 3, 5, \\ldots, 31$, giving $|B| = 16$. The intersection $A \\cap B$ consists of the odd multiples of 7 in this range: 7 and 21, so $|A \\cap B| = 2$. Therefore $P(A \\mid B) = \\frac{|A \\cap B|}{|B|} = \\frac{2}{16} = \\frac{1}{8}$ and $P(B \\mid A) = \\frac{|A \\cap B|}{|A|} = \\frac{2}{4} = \\frac{1}{2}$. The sum is $\\frac{1}{8} + \\frac{1}{2} = \\frac{1}{8} + \\frac{4}{8} = \\frac{5}{8}$.', NULL, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2CZ1OUO', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 2, 'grid_in', E'A rectangular prism has a length of $11$, a width of $7$, and a height of $4$. A pyramid has the same rectangular base and the same height as the prism. What is the volume of the pyramid?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '308/3', ARRAY['308/3', '102.6', '102.7'], E'The volume of a pyramid is $V = \\frac{1}{3} \\times \\text{base area} \\times \\text{height}$. The base area is $11 \\times 7 = 77$. Therefore $V = \\frac{1}{3}(77)(4) = \\frac{308}{3}$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D1V62F', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 3, 'grid_in', E'The rational expression $\\frac{x^2 - 9x + 14}{x^2 - 4}$ is equivalent to $\\frac{x - 7}{x + 2}$ for all values of $x$ for which both expressions are defined. For what value of $x$ is the original expression undefined while the simplified expression $\\frac{x - 7}{x + 2}$ is defined?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '2', ARRAY['2'], E'Factor the numerator: $x^2 - 9x + 14 = (x - 2)(x - 7)$. Factor the denominator: $x^2 - 4 = (x - 2)(x + 2)$. The original expression is undefined when its denominator equals zero, which occurs at $x = 2$ and $x = -2$. Canceling the common factor $(x - 2)$ gives $\\frac{x - 7}{x + 2}$, which is undefined only at $x = -2$. Therefore $x = 2$ is the value where the original expression is undefined but the simplified form is defined. This is the removable discontinuity introduced by the canceled factor.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2D50E8X', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 2, 'mcq', E'A fitness studio randomly assigned 86 of its members into two groups. Group 1 followed a high-intensity interval training program, and Group 2 followed a steady-state cardio program. After 11 weeks, Group 1 showed a significantly greater improvement in cardiovascular endurance than Group 2. Which of the following conclusions is best supported by the study design?', NULL, $lyceon_json$[{"key":"A","text":"High-intensity interval training caused the greater improvement in cardiovascular endurance compared to steady-state cardio among the studio members in the study."},{"key":"B","text":"High-intensity interval training is associated with greater cardiovascular endurance, but no causal conclusion can be drawn."},{"key":"C","text":"The results can be generalized to all adults who exercise regularly."},{"key":"D","text":"Group 1 improved more because its members were naturally more athletic than Group 2."}]$lyceon_json$::jsonb, 'A', NULL, E'Because the 86 members were randomly assigned to the two training programs, confounding variables are expected to balance across the groups. This random assignment supports a causal conclusion: the high-intensity interval program caused the greater improvement among participants in the study. Claiming only an association ignores the causal inference that random assignment permits. Generalizing to all adults who exercise goes beyond what this study supports, since the participants were members of one fitness studio, not a random sample of all exercising adults. Attributing the difference to natural athleticism overlooks that random assignment is designed to equalize such pre-existing differences across groups.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2DAC0OW', 'M', 2, 'Geometry and Trigonometry', ARRAY['Lines, Angles, and Triangles'], 2, 'mcq', E'In triangle $DEF$, the exterior angle at vertex $F$ measures $131°$. If the measure of angle $D$ is $54°$, what is the measure, in degrees, of angle $E$?', NULL, $lyceon_json$[{"key":"A","text":"$49$"},{"key":"B","text":"$77$"},{"key":"C","text":"$85$"},{"key":"D","text":"$126$"}]$lyceon_json$::jsonb, 'B', NULL, E'By the Exterior Angle Theorem, an exterior angle of a triangle equals the sum of the two non-adjacent interior angles. Therefore $131 = 54 + \\text{angle } E$, giving angle $E = 131 - 54 = 77°$. The value $49$ results from computing the interior angle at $F$ as $180 - 131 = 49$ and confusing it with angle $E$. The value $85$ results from an arithmetic error in the subtraction $131 - 54$, obtaining $85$ instead of $77$. The value $126$ comes from computing $180 - 54 = 126$, finding the supplement of angle $D$ while ignoring the exterior angle information entirely.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E1EEM0', 'M', 2, 'Algebra', ARRAY['Systems of Two Linear Equations in Two Variables'], 2, 'mcq', E'A hardware store sells two types of bolts. A contractor purchases $11$ boxes of zinc bolts and $4$ boxes of steel bolts for a total of $143$ dollars. A second contractor purchases $7$ boxes of zinc bolts and $6$ boxes of steel bolts for a total of $129$ dollars. What is the price, in dollars, of one box of steel bolts?', NULL, $lyceon_json$[{"key":"A","text":"$7$"},{"key":"B","text":"$9$"},{"key":"C","text":"$11$"},{"key":"D","text":"$13$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $z$ represent the price of a box of zinc bolts and $s$ the price of a box of steel bolts. The system is $11z + 4s = 143$ and $7z + 6s = 129$. Multiplying the first equation by $3$ gives $33z + 12s = 429$. Multiplying the second equation by $2$ gives $14z + 12s = 258$. Subtracting: $19z = 171$, so $z = 9$. Substituting back: $7(9) + 6s = 129$, yielding $6s = 66$ and $s = 11$. The distractor $9$ is the price of zinc bolts, not steel — a student who solves correctly but answers for the wrong variable would choose it. The distractor $13$ results from an arithmetic slip in the elimination step. The distractor $7$ arises from setting up the equations with swapped coefficients.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2E9R1SI', 'M', 2, 'Algebra', ARRAY['Linear Equations in One Variable'], 1, 'grid_in', E'Solve for $x$: $13x - 7 = 84$', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Add $7$ to both sides of the equation to get $13x = 91$. Dividing both sides by $13$ yields $x = 7$.', NULL, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2EK2WK5', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 1, 'mcq', E'The function $g(x) = 41 - 7x$ models the number of gallons of water remaining in a storage tank after $x$ hours of draining. What does the number $7$ represent in this function?', NULL, $lyceon_json$[{"key":"A","text":"The tank loses 7 gallons each hour"},{"key":"B","text":"The tank initially contained 7 gallons"},{"key":"C","text":"The tank is empty after 7 hours"},{"key":"D","text":"A total of 7 gallons are removed from the tank"}]$lyceon_json$::jsonb, 'A', NULL, E'In the function $g(x) = 41 - 7x$, the coefficient $7$ multiplies the input variable $x$ (hours), so it represents the rate of change: the tank loses $7$ gallons per hour. Confusing $7$ with the initial amount mistakes the coefficient for the constant; the initial amount is $41$ gallons. Claiming the tank is empty after $7$ hours confuses the rate with the time to empty (which is $41/7 \\approx 5.86$ hours). Interpreting $7$ as a total amount removed misunderstands a rate as a fixed quantity.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"misread_question"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 50, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FQB2EK', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 1, 'grid_in', E'What is the positive solution of $2x^2 - 9x - 35 = 0$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '7', ARRAY['7'], E'Factor the quadratic: find two numbers whose product is $2 \\times (-35) = -70$ and whose sum is $-9$. Those numbers are $-14$ and $5$. Rewrite: $2x^2 - 14x + 5x - 35 = 2x(x - 7) + 5(x - 7) = (2x + 5)(x - 7) = 0$. Setting each factor to zero gives $x = -\\frac{5}{2}$ or $x = 7$. The positive solution is $7$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2FUHCP3', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 3, 'grid_in', E'The cost, in dollars, to produce $n$ widgets at a factory is modeled by the linear function $C(n) = 14n + 230$. The factory sells each widget for 23 dollars. What is the minimum number of whole widgets the factory must sell so that revenue from sales exceeds the production cost?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '26', ARRAY['26'], E'Revenue from selling $n$ widgets is $R(n) = 23n$. The factory makes a profit when $23n > 14n + 230$. Subtracting $14n$ from both sides gives $9n > 230$, so $n > \\frac{230}{9} \\approx 25.56$. Since $n$ must be a whole number, the minimum is $n = 26$. At $n = 25$, revenue is $575$ and cost is $580$, confirming that $25$ is not enough. At $n = 26$, revenue is $598$ and cost is $594$, confirming profit.', NULL, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2G4H3FB', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 3, 'mcq', E'Researchers wanted to test whether a new phosphorus-based fertilizer increases tomato yield. They recruited 54 volunteer gardeners from a regional gardening club. Each volunteer was randomly assigned to use either the new fertilizer or a standard fertilizer on an identical-sized plot. After the growing season, the mean yield for the new-fertilizer group was significantly higher than for the standard-fertilizer group. Which of the following conclusions is justified by the study design?', NULL, $lyceon_json$[{"key":"A","text":"The new fertilizer causes higher tomato yields for all gardeners."},{"key":"B","text":"The new fertilizer causes higher tomato yields among gardeners similar to the volunteers in the study."},{"key":"C","text":"The new fertilizer is associated with, but cannot be said to cause, higher tomato yields."},{"key":"D","text":"No valid conclusion can be drawn because the gardeners were not randomly selected from a larger population."}]$lyceon_json$::jsonb, 'B', NULL, E'The study uses random assignment of volunteers to treatments, which supports a causal conclusion: the new fertilizer caused the higher yield. However, because the participants were volunteers from one gardening club rather than a random sample of all gardeners, the results can only be generalized to gardeners similar to those volunteers — not to all gardeners everywhere. Claiming causation for all gardeners overgeneralizes beyond the study''s non-random sample. Denying causation entirely ignores that random assignment controls for confounding variables and does permit causal inference. Claiming no valid conclusion can be drawn mistakes the lack of random selection as invalidating the experiment; random assignment still supports causation within the study population, even when generalizing is limited.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"misread_question"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2GJLVOF', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 3, 'mcq', E'A water tank is shaped like a right circular cylinder topped with a hemisphere. The cylinder has a radius of $6$ feet and a height of $15$ feet. The hemisphere has the same radius as the cylinder. What is the total volume of the tank, in cubic feet?', NULL, $lyceon_json$[{"key":"A","text":"$540\\pi$"},{"key":"B","text":"$612\\pi$"},{"key":"C","text":"$684\\pi$"},{"key":"D","text":"$828\\pi$"}]$lyceon_json$::jsonb, 'C', NULL, E'The cylinder volume is $\\pi r^2 h = \\pi(36)(15) = 540\\pi$. The hemisphere volume is $\\frac{2}{3}\\pi r^3 = \\frac{2}{3}\\pi(216) = 144\\pi$. The total is $540\\pi + 144\\pi = 684\\pi$ cubic feet. The value $540\\pi$ comes from computing only the cylinder volume and omitting the hemisphere. The value $612\\pi$ comes from using $\\frac{1}{3}\\pi r^3 = 72\\pi$ for the hemisphere (omitting the factor of $2$ in the hemisphere formula), giving $540\\pi + 72\\pi = 612\\pi$. The value $828\\pi$ comes from using the full sphere volume $\\frac{4}{3}\\pi r^3 = 288\\pi$ instead of the hemisphere, giving $540\\pi + 288\\pi = 828\\pi$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2HQPUDK', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 3, 'mcq', E'A biologist models the relationship between the concentration of a nutrient, $x$ (in mg/L), and the growth rate of a bacterial colony, $y$ (in colonies per hour), using an exponential model of the form $y = a \\cdot b^x$. At a concentration of 0 mg/L the growth rate is 5 colonies per hour, and at a concentration of 3 mg/L the growth rate is 135 colonies per hour. According to this model, what is the predicted growth rate, in colonies per hour, at a concentration of 5 mg/L?', NULL, $lyceon_json$[{"key":"A","text":"$243$"},{"key":"B","text":"$675$"},{"key":"C","text":"$1{,}215$"},{"key":"D","text":"$3{,}645$"}]$lyceon_json$::jsonb, 'C', NULL, E'At $x = 0$: $y = a \\cdot b^0 = a = 5$. At $x = 3$: $5 \\cdot b^3 = 135$, so $b^3 = 27$ and $b = 3$. At $x = 5$: $y = 5 \\cdot 3^5 = 5 \\times 243 = 1{,}215$. The value 243 equals $3^5$ alone, omitting the multiplication by $a = 5$. The value 675 results from multiplying the known growth rate at $x = 3$ by the target concentration ($135 \\times 5 = 675$), applying a linear scaling rather than the exponential model. The value 3,645 results from computing $5 \\cdot 3^6 = 5 \\times 729 = 3{,}645$, using an exponent of 6 instead of 5.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2INMV08', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 2, 'grid_in', E'A teacher recorded the following quiz scores for 9 students, listed in ascending order: $41, 55, 62, 68, 73, 77, 84, 89, 93$. If the lowest score is removed from the dataset, what is the median of the remaining 8 scores?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '75', ARRAY['75'], E'After removing the lowest score of 41, the remaining 8 values in order are: $55, 62, 68, 73, 77, 84, 89, 93$. For an even-count dataset, the median is the average of the 4th and 5th values: $\\frac{73 + 77}{2} = 75$. A common error is to keep the original median of the 9-value set (the 5th value, 73) without recalculating after the removal. Another error is to select just one of the two middle values (73 or 77) instead of averaging them.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2IPJ4SG', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 1, 'mcq', E'A circle has a diameter of $46$. What is the circumference of the circle?', NULL, $lyceon_json$[{"key":"A","text":"$23\\pi$"},{"key":"B","text":"$46\\pi$"},{"key":"C","text":"$529\\pi$"},{"key":"D","text":"$2{,}116\\pi$"}]$lyceon_json$::jsonb, 'B', NULL, E'The circumference of a circle is $C = \\pi d$, where $d$ is the diameter. Substituting $d = 46$ gives $C = 46\\pi$. The value $23\\pi$ results from using the radius ($23$) instead of the diameter in the circumference formula, computing $\\pi r$ instead of $\\pi d$. The value $529\\pi$ results from using the area formula for a circle with radius $23$: $\\pi r^2 = \\pi(23)^2 = 529\\pi$. The value $2{,}116\\pi$ results from squaring the diameter instead of the radius: $\\pi(46)^2 = 2{,}116\\pi$.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2J1P0J1', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 2, 'mcq', E'A laptop originally costs 1,240 dollars. It is first discounted by $15\\%$, and then an additional $10\\%$ discount is applied to the already-reduced price. What is the final price of the laptop, in dollars?', NULL, $lyceon_json$[{"key":"A","text":"$930$"},{"key":"B","text":"$948.60$"},{"key":"C","text":"$1{,}054$"},{"key":"D","text":"$1{,}116$"}]$lyceon_json$::jsonb, 'B', NULL, E'After the first discount: $1{,}240 \\times 0.85 = 1{,}054$. After the second discount applied to the reduced price: $1{,}054 \\times 0.90 = 948.60$. The value 930 results from combining the two discounts into a single $25\\%$ discount ($1{,}240 \\times 0.75 = 930$), which incorrectly assumes successive percentages are additive rather than multiplicative. The value 1,054 results from applying only the first $15\\%$ discount and stopping, omitting the second discount entirely. The value 1,116 results from applying only the $10\\%$ discount ($1{,}240 \\times 0.90 = 1{,}116$), ignoring the first discount.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2JMQLEY', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 3, 'mcq', E'The graph of $h(x) = -2(x + 5)^2 + 18$ is reflected over the $x$-axis and then translated $4$ units to the right and $3$ units down. What is the vertex of the resulting parabola?', NULL, $lyceon_json$[{"key":"A","text":"$(-1, -21)$"},{"key":"B","text":"$(-1, -15)$"},{"key":"C","text":"$(-9, -21)$"},{"key":"D","text":"$(9, -21)$"}]$lyceon_json$::jsonb, 'A', NULL, E'The original function $h(x) = -2(x + 5)^2 + 18$ has vertex $(-5, 18)$. Reflecting over the $x$-axis negates all $y$-values, moving the vertex to $(-5, -18)$. Translating $4$ units right shifts the $x$-coordinate: $-5 + 4 = -1$. Translating $3$ units down shifts the $y$-coordinate: $-18 - 3 = -21$. The resulting vertex is $(-1, -21)$. The distractor $(-1, -15)$ results from adding $3$ instead of subtracting during the downward translation. The distractor $(-9, -21)$ results from translating $4$ units to the left instead of to the right. The distractor $(9, -21)$ results from misreading the original vertex as $(5, 18)$ instead of $(-5, 18)$ and then shifting right by $4$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"sign_error"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2M4JA0E', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 2, 'mcq', E'A researcher surveyed 400 randomly selected households in a large metropolitan area and found that the mean monthly electricity bill was 127 dollars with a margin of error of 9 dollars. Which of the following conclusions is best supported by the survey results?', NULL, $lyceon_json$[{"key":"A","text":"The mean monthly electricity bill for all households in the metropolitan area is exactly 127 dollars."},{"key":"B","text":"The mean monthly electricity bill for all households in the metropolitan area is between 118 and 136 dollars."},{"key":"C","text":"Every household in the metropolitan area pays between 118 and 136 dollars per month for electricity."},{"key":"D","text":"Approximately 9 percent of households pay more than 127 dollars per month."}]$lyceon_json$::jsonb, 'B', NULL, E'The margin of error defines a confidence interval for the population mean: $127 - 9 = 118$ to $127 + 9 = 136$ dollars. This interval estimates where the true mean lies, not the exact value nor the range of individual bills. Claiming the mean is exactly 127 dollars treats the sample statistic as the population parameter, ignoring sampling variability. Stating that every household pays within that range misinterprets the confidence interval as applying to individual values rather than the population mean. Interpreting the margin of error as a percentage of households who pay above the mean confuses the margin of error with a proportion.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2MT10OL', 'M', 2, 'Geometry and Trigonometry', ARRAY['Circles'], 2, 'grid_in', E'A sector of a circle with radius $6$ has an area of $21\\pi$ square units. What is the measure of the central angle of the sector, in degrees?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '210', ARRAY['210'], E'The area of a sector is $A = \\frac{\\theta}{360} \\cdot \\pi r^2$. Substituting gives $21\\pi = \\frac{\\theta}{360} \\cdot \\pi(36)$. Dividing both sides by $\\pi$ gives $21 = \\frac{36\\theta}{360} = \\frac{\\theta}{10}$. Therefore $\\theta = 210°$.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OFE4DB', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Equations in One Variable and Systems of Equations in Two Variables'], 2, 'grid_in', E'The equation $3x^2 + kx + 27 = 0$, where $k$ is a positive constant, has exactly one real solution. What is the value of $k$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '18', ARRAY['18'], E'A quadratic equation $ax^2 + bx + c = 0$ has exactly one real solution when its discriminant equals zero: $b^2 - 4ac = 0$. Here $a = 3$, $b = k$, and $c = 27$, so $k^2 - 4(3)(27) = 0$. This gives $k^2 = 324$, so $k = \\pm 18$. Since $k$ is stated to be positive, $k = 18$.', NULL, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ONA40V', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 3, 'mcq', E'From the top of a building $83$ feet tall, the angle of depression to a point on the ground is $29°$. From the same point on the ground, the angle of elevation to the top of a flagpole standing on the building''s roof is $37°$. What is the height of the flagpole, in feet, to the nearest whole number?', NULL, $lyceon_json$[{"key":"A","text":"$12$"},{"key":"B","text":"$17$"},{"key":"C","text":"$30$"},{"key":"D","text":"$113$"}]$lyceon_json$::jsonb, 'C', NULL, E'Let $d$ be the horizontal distance from the ground point to the building. The angle of depression of $29°$ gives $\\tan(29°) = \\frac{83}{d}$, so $d = \\frac{83}{\\tan(29°)}$. If $h$ is the flagpole height, the angle of elevation of $37°$ to the flagpole top gives $\\tan(37°) = \\frac{83 + h}{d}$, so $83 + h = d \\tan(37°) = \\frac{83 \\tan(37°)}{\\tan(29°)} \\approx \\frac{83(0.7536)}{0.5543} \\approx 112.8$. Thus $h \\approx 112.8 - 83 = 29.8 \\approx 30$ feet. The value $12$ comes from using the difference of angles ($37° - 29° = 8°$) and computing $83 \\tan(8°) \\approx 12$, incorrectly treating the angle difference as a single angle for the flagpole. The value $17$ comes from computing $83(\\tan(37°) - \\tan(29°)) \\approx 17$, incorrectly distributing the tangent over a difference. The value $113$ comes from computing $\\frac{83 \\tan(37°)}{\\tan(29°)} \\approx 113$ but forgetting to subtract the building height of $83$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"equation_setup_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OO6OVQ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['One-Variable Data: Distributions and Measures of Center and Spread'], 1, 'mcq', E'A dataset consists of the following 6 values: $13, 19, 23, 31, 35, 47$. What is the median of this dataset?', NULL, $lyceon_json$[{"key":"A","text":"$23$"},{"key":"B","text":"$27$"},{"key":"C","text":"$28$"},{"key":"D","text":"$54$"}]$lyceon_json$::jsonb, 'B', NULL, E'With 6 values in ascending order, the median is the average of the 3rd and 4th values: $\\frac{23 + 31}{2} = 27$. The value 23 results from selecting only the 3rd value without averaging it with the 4th, which is incomplete for an even-count dataset. The value 28 is the mean of the dataset ($\\frac{13 + 19 + 23 + 31 + 35 + 47}{6} = \\frac{168}{6} = 28$), which confuses the mean with the median. The value 54 results from adding the two middle values ($23 + 31 = 54$) but forgetting to divide by 2.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"arithmetic_slip"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2OV79QY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 2, 'mcq', E'A two-way frequency table summarizes the lunch preferences of 130 employees at a company.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P2AIUX', 'M', 2, 'Algebra', ARRAY['Linear Functions'], 2, 'mcq', E'A linear function $h$ satisfies $h(2) = 19$ and $h(5) = 37$. What is the value of $h(0)$?', NULL, $lyceon_json$[{"key":"A","text":"$6$"},{"key":"B","text":"$7$"},{"key":"C","text":"$13$"},{"key":"D","text":"$31$"}]$lyceon_json$::jsonb, 'B', NULL, E'The slope is $m = \\frac{37 - 19}{5 - 2} = \\frac{18}{3} = 6$. Using $h(2) = 19$: $19 = 6(2) + b$, so $b = 7$. Thus $h(0) = 7$. The value $6$ comes from reporting the slope instead of evaluating the function at $0$. The value $13$ results from a miscalculation such as subtracting the slope once ($19 - 6 = 13$) instead of twice ($19 - 12 = 7$) when working back from $x = 2$ to $x = 0$. The value $31$ arises from adding $2 \\times 6$ to $19$ instead of subtracting, effectively extrapolating in the wrong direction.', $lyceon_json${"B":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2P72B35', 'M', 2, 'Advanced Math', ARRAY['Equivalent Expressions'], 2, 'mcq', E'Which of the following is equivalent to $10x^2 + 29x - 21$?', NULL, $lyceon_json$[{"key":"A","text":"$(2x + 7)(5x - 3)$"},{"key":"B","text":"$(2x - 3)(5x + 7)$"},{"key":"C","text":"$(10x + 7)(x - 3)$"},{"key":"D","text":"$(2x + 3)(5x - 7)$"}]$lyceon_json$::jsonb, 'A', NULL, E'To factor $10x^2 + 29x - 21$, find two numbers whose product is $10 \\times (-21) = -210$ and whose sum is $29$. The numbers $35$ and $-6$ satisfy this: $35 \\times (-6) = -210$ and $35 + (-6) = 29$. Rewriting: $10x^2 + 35x - 6x - 21 = 5x(2x + 7) - 3(2x + 7) = (2x + 7)(5x - 3)$. The expression $(2x - 3)(5x + 7) = 10x^2 + 14x - 15x - 21 = 10x^2 - x - 21$, which has the wrong middle term due to sign errors in the factor pair. The expression $(10x + 7)(x - 3) = 10x^2 - 30x + 7x - 21 = 10x^2 - 23x - 21$, which results from an incorrect grouping of factors. The expression $(2x + 3)(5x - 7) = 10x^2 - 14x + 15x - 21 = 10x^2 + x - 21$, which swaps the signs in both binomials.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"equation_setup_error"},"D":{"role":"distractor","error_taxonomy":"sign_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PBSNTN', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 1, 'mcq', E'A print shop uses 19 sheets of specialty paper for every 3 posters it produces. How many sheets of specialty paper are needed to print 27 posters?', NULL, $lyceon_json$[{"key":"A","text":"$152$"},{"key":"B","text":"$171$"},{"key":"C","text":"$189$"},{"key":"D","text":"$513$"}]$lyceon_json$::jsonb, 'B', NULL, E'The ratio is 19 sheets per 3 posters, so for 27 posters the number of sheets is $\\frac{19}{3} \\times 27 = 19 \\times 9 = 171$. The value 152 results from an arithmetic slip computing $27 \\div 3 = 8$ instead of $9$, yielding $19 \\times 8 = 152$. The value 189 results from using $27 \\times 7$, misreading the given numbers. The value 513 results from multiplying $19 \\times 27$ without dividing by 3, setting up the proportion incorrectly.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2PIV2FS', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Percentages'], 1, 'mcq', E'A ceramics shop prices a decorative vase at 74 dollars. During a seasonal sale, the vase is marked down by $35\\%$. What is the sale price, in dollars, of the vase?', NULL, $lyceon_json$[{"key":"A","text":"$25.90$"},{"key":"B","text":"$39.00$"},{"key":"C","text":"$48.10$"},{"key":"D","text":"$51.80$"}]$lyceon_json$::jsonb, 'C', NULL, E'The sale price is $74 \\times (1 - 0.35) = 74 \\times 0.65 = 48.10$ dollars. The value 25.90 equals $74 \\times 0.35$, which is only the discount amount rather than the final price. The value 39.00 results from subtracting 35 as a dollar amount ($74 - 35 = 39$) instead of computing $35\\%$ of 74, confusing the percentage with a flat dollar reduction. The value 51.80 results from applying a $30\\%$ discount ($74 \\times 0.70 = 51.80$) instead of $35\\%$, misreading the discount rate.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2R2X0TU', 'M', 2, 'Geometry and Trigonometry', ARRAY['Area and Volume'], 1, 'mcq', E'A rectangular garden has a length of $27$ feet and a width of $13$ feet. What is the area, in square feet, of the garden?', NULL, $lyceon_json$[{"key":"A","text":"$40$"},{"key":"B","text":"$80$"},{"key":"C","text":"$341$"},{"key":"D","text":"$351$"}]$lyceon_json$::jsonb, 'D', NULL, E'The area of a rectangle is length times width: $27 \\times 13 = 351$ square feet. The value $40$ comes from adding $27 + 13 = 40$, computing only half the perimeter instead of the area. The value $80$ comes from computing the full perimeter $2(27 + 13) = 80$, confusing perimeter with area. The value $341$ results from an arithmetic slip in the multiplication: computing $27 \\times 13$ as $270 + 71 = 341$ instead of the correct $270 + 81 = 351$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2RY4WEW', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 2, 'mcq', E'A researcher models the relationship between altitude and temperature at a mountain station using the line of best fit $y = -3.6x + 89.2$, where $x$ is the altitude in thousands of feet and $y$ is the temperature in degrees Fahrenheit. According to this model, for every increase of 2,500 feet in altitude, the temperature is predicted to decrease by how many degrees Fahrenheit?', NULL, $lyceon_json$[{"key":"A","text":"$3.6$"},{"key":"B","text":"$7.2$"},{"key":"C","text":"$9$"},{"key":"D","text":"$90$"}]$lyceon_json$::jsonb, 'C', NULL, E'Since $x$ is measured in thousands of feet, an increase of 2,500 feet corresponds to $\\Delta x = 2.5$. The predicted temperature change is $-3.6 \\times 2.5 = -9.0$, so the temperature decreases by 9 degrees Fahrenheit. The value 3.6 results from reporting the slope magnitude without scaling it for the 2,500-foot increase, which gives only the change per 1,000 feet. The value 7.2 results from an arithmetic slip converting 2,500 feet to 2 thousand instead of 2.5 thousand, giving $3.6 \\times 2 = 7.2$. The value 90 results from a unit error — using 2,500 directly as 25 (hundreds) rather than converting to 2.5 (thousands), giving $3.6 \\times 25 = 90$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"unit_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TMHNJ3', 'M', 2, 'Advanced Math', ARRAY['Nonlinear Functions'], 2, 'mcq', E'The function $f$ is defined by $f(x) = 7 \\cdot 3^x$. For any value of $x$, $f(x + 3) = a \\cdot f(x)$, where $a$ is a constant. What is the value of $a$?', NULL, $lyceon_json$[{"key":"A","text":"$9$"},{"key":"B","text":"$21$"},{"key":"C","text":"$27$"},{"key":"D","text":"$189$"}]$lyceon_json$::jsonb, 'C', NULL, E'Evaluate $f(x + 3) = 7 \\cdot 3^{x+3} = 7 \\cdot 3^x \\cdot 3^3 = 7 \\cdot 3^x \\cdot 27 = 27 \\cdot f(x)$. Therefore $a = 27$. Choosing $9$ results from computing $3^2$ instead of $3^3$. Choosing $21$ results from multiplying the coefficient $7$ by the base $3$ instead of computing the exponential growth factor. Choosing $189$ results from computing $7 \\times 27 = 189$, treating the entire expression $f(x + 3)$ as the multiplier rather than recognizing that the factor of $7$ is already contained in $f(x)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2TZZUYY', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Probability and Conditional Probability'], 1, 'mcq', E'A wildlife rescue center houses 47 birds: 19 are raptors, 13 are songbirds, and 15 are waterfowl. If one bird is selected at random for a veterinary checkup, what is the probability that the selected bird is a songbird?', NULL, $lyceon_json$[{"key":"A","text":"$\\frac{13}{47}$"},{"key":"B","text":"$\\frac{13}{34}$"},{"key":"C","text":"$\\frac{19}{47}$"},{"key":"D","text":"$\\frac{15}{47}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The probability of selecting a songbird is the number of songbirds divided by the total number of birds: $\\frac{13}{47}$. The value $\\frac{13}{34}$ results from incorrectly using only the non-songbird categories ($19 + 15 = 34$) as the denominator instead of the full total of 47. The value $\\frac{19}{47}$ is the probability of selecting a raptor, and $\\frac{15}{47}$ is the probability of selecting a waterfowl — both answer a different question than what was asked.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"concept_gap"},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"misread_question"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2URCZD2', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 1, 'mcq', E'A city surveyed a random sample of 230 residents and found that the mean commute time was 37 minutes with a margin of error of 4 minutes. Which of the following is the most plausible range for the mean commute time of all residents in the city?', NULL, $lyceon_json$[{"key":"A","text":"Between 33 and 41 minutes"},{"key":"B","text":"Between 37 and 41 minutes"},{"key":"C","text":"Between 35 and 39 minutes"},{"key":"D","text":"Between 29 and 45 minutes"}]$lyceon_json$::jsonb, 'A', NULL, E'A margin of error of 4 minutes means the confidence interval extends 4 minutes in each direction from the sample mean: $37 - 4 = 33$ to $37 + 4 = 41$, giving the range 33 to 41 minutes. The range 37 to 41 only adds the margin of error to the mean without subtracting it, capturing only the upper half of the interval. The range 35 to 39 uses a margin of only 2 minutes instead of 4, halving the stated margin of error. The range 29 to 45 doubles the margin of error to 8, applying $37 \\pm 8$ instead of $37 \\pm 4$.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2W60SYE', 'M', 2, 'Algebra', ARRAY['Linear Equations in Two Variables'], 1, 'mcq', E'What is the $y$-intercept of the line $11x - 6y = 54$?', NULL, $lyceon_json$[{"key":"A","text":"$-9$"},{"key":"B","text":"$9$"},{"key":"C","text":"$-\\frac{54}{11}$"},{"key":"D","text":"$\\frac{54}{6}$"}]$lyceon_json$::jsonb, 'A', NULL, E'The $y$-intercept occurs when $x = 0$. Substituting into $11(0) - 6y = 54$ gives $-6y = 54$, so $y = -9$. The value $9$ results from dividing $54$ by $6$ but neglecting the negative sign from $-6y = 54$. The value $-\\frac{54}{11}$ results from setting $y = 0$ and solving for $x$, which gives the $x$-intercept instead. The value $\\frac{54}{6}$ results from dividing the constant by the coefficient of $y$ without accounting for the negative sign, yielding $9$ written as a fraction.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2WRBY3T', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 1, 'grid_in', E'In a right triangle, the two legs have lengths $17$ and $31$. What is the value of $\\tan(\\theta)$, where $\\theta$ is the angle opposite the leg of length $17$?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '17/31', ARRAY['17/31', '0.548', '.548'], E'The tangent of an angle in a right triangle is the ratio of the opposite side to the adjacent side. For the angle opposite the leg of length $17$, the adjacent leg has length $31$. Therefore $\\tan(\\theta) = \\frac{17}{31}$.', NULL, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XG5RGJ', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Two-Variable Data: Models and Scatterplots'], 1, 'mcq', E'A line of best fit for a scatterplot is given by $y = 4.1x + 5.3$. Using this model, what is the predicted value of $y$ when $x = 7$?', NULL, $lyceon_json$[{"key":"A","text":"$9.4$"},{"key":"B","text":"$23.4$"},{"key":"C","text":"$28.7$"},{"key":"D","text":"$34.0$"}]$lyceon_json$::jsonb, 'D', NULL, E'Substituting $x = 7$: $y = 4.1(7) + 5.3 = 28.7 + 5.3 = 34.0$. The value 9.4 results from adding the coefficients ($4.1 + 5.3 = 9.4$) instead of substituting $x = 7$ into the equation. The value 23.4 results from subtracting the constant ($28.7 - 5.3 = 23.4$) instead of adding it, a sign error. The value 28.7 results from computing $4.1 \\times 7 = 28.7$ but stopping without adding the $y$-intercept of 5.3.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"equation_setup_error"},"B":{"role":"distractor","error_taxonomy":"sign_error"},"C":{"role":"distractor","error_taxonomy":"partial_reasoning"},"D":{"role":"correct","error_taxonomy":null}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XJTUO6', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Evaluating Statistical Claims: Observational Studies and Experiments'], 1, 'mcq', E'Researchers recorded the daily water intake and skin elasticity scores of 310 adults over a period of three months. They found that adults who drank more water tended to have higher skin elasticity scores. What type of study did the researchers conduct?', NULL, $lyceon_json$[{"key":"A","text":"A randomized controlled experiment"},{"key":"B","text":"An observational study"},{"key":"C","text":"A census"},{"key":"D","text":"An experiment with a control group and a treatment group"}]$lyceon_json$::jsonb, 'B', NULL, E'The researchers recorded existing behaviors (water intake) and measured an outcome (skin elasticity) without assigning participants to specific water intake levels. Because no treatment was imposed or randomly assigned, this is an observational study. A randomized controlled experiment would require the researchers to randomly assign participants to different water intake levels, which did not occur. A census involves collecting data from every member of a population, not a sample of 310 adults. Describing the study as having a control group and treatment group imposes an experimental structure that was not part of the study design.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"misread_question"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 45, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XNWDAP', 'M', 2, 'Algebra', ARRAY['Linear Inequalities in One or Two Variables'], 2, 'mcq', E'Which of the following ordered pairs $(x, y)$ is a solution to the inequality $5x - 3y > 19$?', NULL, $lyceon_json$[{"key":"A","text":"$(3, -1)$"},{"key":"B","text":"$(4, 1)$"},{"key":"C","text":"$(5, 1)$"},{"key":"D","text":"$(2, -3)$"}]$lyceon_json$::jsonb, 'C', NULL, E'Substituting $(5, 1)$: $5(5) - 3(1) = 25 - 3 = 22$, and $22 > 19$ is true, so this pair satisfies the strict inequality. For $(3, -1)$: $5(3) - 3(-1) = 15 + 3 = 18$, and $18 > 19$ is false. For $(4, 1)$: $5(4) - 3(1) = 20 - 3 = 17$, and $17 > 19$ is false. For $(2, -3)$: $5(2) - 3(-3) = 10 + 9 = 19$, and $19 > 19$ is false because the inequality is strict — a student who confuses $>$ with $\\geq$ would incorrectly accept this boundary value.', $lyceon_json${"C":{"role":"correct","error_taxonomy":null},"A":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"B":{"role":"distractor","error_taxonomy":"arithmetic_slip"},"D":{"role":"distractor","error_taxonomy":"concept_gap"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2XY89WU', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Inference from Sample Statistics and Margin of Error'], 3, 'mcq', E'Two independent random surveys were conducted in neighboring towns to estimate mean monthly rent. In Town X, a sample of 180 renters had a mean rent of 1,340 dollars with a margin of error of 65 dollars. In Town Y, a sample of 150 renters had a mean rent of 1,410 dollars with a margin of error of 80 dollars. Which of the following statements is best supported by these survey results?', NULL, $lyceon_json$[{"key":"A","text":"The mean monthly rent in Town Y is definitely higher than in Town X."},{"key":"B","text":"The mean monthly rents in the two towns are equal."},{"key":"C","text":"The data do not provide sufficient evidence to conclude that the mean monthly rents in the two towns are different."},{"key":"D","text":"Town X has a lower mean rent because its margin of error is smaller."}]$lyceon_json$::jsonb, 'C', NULL, E'The confidence interval for Town X is $1{,}340 \\pm 65$, or $[1{,}275, 1{,}405]$. The confidence interval for Town Y is $1{,}410 \\pm 80$, or $[1{,}330, 1{,}490]$. These intervals overlap in the range $[1{,}330, 1{,}405]$, meaning the true population means could plausibly be equal. Because the intervals overlap, the data do not provide sufficient evidence to conclude the means differ. Claiming Town Y definitely has a higher mean ignores sampling variability and the overlapping intervals. Claiming the means are equal goes beyond what the data support — overlap shows we cannot distinguish them, not that they are identical. Asserting that a smaller margin of error implies a lower mean confuses precision of the estimate with the estimate itself.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2YY9PV4', 'M', 2, 'Problem Solving and Data Analysis', ARRAY['Ratios, Rates, Proportional Relationships, and Units'], 3, 'grid_in', E'A paint mixer creates a custom color by combining red, blue, and white pigments. The ratio of red pigment to blue pigment is $3:7$, and the ratio of blue pigment to white pigment is $2:5$. If the mixer uses 42 ounces of blue pigment, how many total ounces of the custom color are produced?', NULL, $lyceon_json$[]$lyceon_json$::jsonb, '165', ARRAY['165'], E'From the ratio red to blue $= 3:7$ with 42 ounces of blue, the red amount is $42 \\times \\frac{3}{7} = 18$ ounces. From the ratio blue to white $= 2:5$ with 42 ounces of blue, the white amount is $42 \\times \\frac{5}{2} = 105$ ounces. The total is $18 + 42 + 105 = 165$ ounces. A common error is combining the two ratios incorrectly — for example, treating the overall ratio as $3:7:5$ (ignoring that blue appears in both ratios with different scale factors), which would give $\\frac{3}{15} \\times 42 + 42 + \\frac{5}{15} \\times 42 = 8.4 + 42 + 14 = 64.4$. The key insight is that the blue pigment quantity anchors both ratios independently.', NULL, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATM2ZOU5JP', 'M', 2, 'Geometry and Trigonometry', ARRAY['Right Triangles and Trigonometry'], 2, 'mcq', E'In right triangle $JKL$, the right angle is at vertex $K$. If $JK = 19$ and the measure of angle $J$ is $34°$, what is the length of $\\overline{KL}$, to the nearest tenth?', NULL, $lyceon_json$[{"key":"A","text":"$10.6$"},{"key":"B","text":"$12.8$"},{"key":"C","text":"$15.7$"},{"key":"D","text":"$28.2$"}]$lyceon_json$::jsonb, 'B', NULL, E'Side $\\overline{KL}$ is opposite angle $J$, and $\\overline{JK} = 19$ is adjacent to angle $J$. Using $\\tan(34°) = \\frac{KL}{19}$ gives $KL = 19 \\tan(34°) \\approx 19(0.6745) \\approx 12.8$. The value $10.6$ comes from incorrectly using sine ($19 \\sin(34°) \\approx 10.6$), treating the adjacent side as the hypotenuse. The value $15.7$ comes from incorrectly using cosine ($19 \\cos(34°) \\approx 15.7$), confusing opposite and adjacent roles. The value $28.2$ comes from inverting the tangent ratio, computing $\\frac{19}{\\tan(34°)} \\approx 28.2$ instead of $19 \\tan(34°)$.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"concept_gap"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"concept_gap"},"D":{"role":"distractor","error_taxonomy":"equation_setup_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW21XIO9N', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Cognitive scientist Lera Boroditsky has shown that speakers of Kuuk Thaayorre, an Aboriginal Australian language, orient spatial descriptions using cardinal directions rather than relative terms like "left" or "right." This practice appears to sharpen navigational awareness: Kuuk Thaayorre speakers maintain an accurate sense of compass orientation even in unfamiliar indoor settings. ______ Boroditsky cautions that the relationship between language and spatial cognition is not strictly deterministic, since English speakers can also be trained to adopt cardinal-direction frameworks with sustained practice.', $lyceon_json$[{"key":"A","text":"Furthermore,"},{"key":"B","text":"That is,"},{"key":"C","text":"Even so,"},{"key":"D","text":"In addition,"}]$lyceon_json$::jsonb, 'C', NULL, E'The preceding sentences build a case that the Kuuk Thaayorre language shapes spatial cognition in a distinctive way. The final sentence then qualifies that claim by noting the relationship is not deterministic. "Even so," correctly introduces this concession — it acknowledges the preceding evidence while signaling that Boroditsky tempers its implications. "Furthermore," and "In addition," both signal additive continuation, but the final sentence does not add supporting evidence; it introduces a qualification. "That is," signals a restatement or clarification, but the final sentence does not rephrase the previous point — it limits its scope.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW22E1C0E', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 2, 'mcq', E'Which choice most logically completes the text?', E'Economists studying labor mobility in the European Union have noted a paradox: despite the EU''s freedom-of-movement provisions, cross-border migration rates among EU citizens remain far lower than interstate migration rates in the United States. Linguistic barriers are frequently cited as the primary explanation, yet migration rates between Austria and Germany — two countries sharing a common language — are only marginally higher than the EU average. Similarly, migration between the francophone regions of Belgium, France, and Switzerland shows no dramatic departure from the overall pattern. This suggests that ________', $lyceon_json$[{"key":"A","text":"linguistic barriers are likely not the principal factor suppressing cross-border labor mobility within the EU."},{"key":"B","text":"EU freedom-of-movement provisions have had no measurable effect on cross-border migration patterns."},{"key":"C","text":"cross-border migration rates in the EU are now equivalent to interstate migration rates in the United States."},{"key":"D","text":"Austrian and German workers prefer to migrate to non-German-speaking EU countries for higher wages."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents evidence that removing the linguistic barrier (by examining countries sharing a language) does not substantially increase migration rates, undermining the claim that language is the primary factor. The logical inference is that linguistic barriers are likely not the principal factor suppressing cross-border labor mobility. The claim that freedom-of-movement provisions have had no measurable effect goes beyond the evidence, which compares EU rates to US rates without evaluating what rates would be without the provisions. The claim that EU and US migration rates are now equivalent directly contradicts the passage''s statement that EU rates remain far lower. The suggestion about Austrian and German workers preferring non-German-speaking countries introduces a claim unsupported by anything in the passage.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW24Y8CPU', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The collection of handwritten manuscripts belonging to the monastery''s library ______ one of the most comprehensive archives of medieval pharmaceutical knowledge in Eastern Europe, containing detailed recipes for herbal remedies and surgical procedures that predate the oldest known European medical textbooks by at least two centuries.', $lyceon_json$[{"key":"A","text":"represents"},{"key":"B","text":"represent"},{"key":"C","text":"are representing"},{"key":"D","text":"have represented"}]$lyceon_json$::jsonb, 'A', NULL, E'The subject of the sentence is "The collection," a singular noun. The intervening prepositional phrases "of handwritten manuscripts" and "belonging to the monastery''s library" do not change the number of the subject. A singular subject requires a singular verb, so "represents" is correct. The plural verb "represent" incorrectly treats "manuscripts" as the subject. "Are representing" fails on two counts: "are" does not agree with the singular subject, and the progressive aspect is inappropriate for a stative description of what the collection constitutes. "Have represented" uses the plural auxiliary "have" rather than the singular "has" required by the singular subject "collection."', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25079OE', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The gallery''s retrospective featured three landmark works of kinetic sculpture: Maren Jørgensen''s ''Pendulum Chorus,'' a suspended array of brass rods and tempered ______ Yuto Kobayashi''s ''Salt Meridian,'' a rotating assemblage of glass prisms, copper wire, and granulated sea salt; and Adaeze Okafor''s ''Breathing Wall,'' a pneumatic installation powered by barometric sensors and latex membranes.', $lyceon_json$[{"key":"A","text":"glass; Yuto"},{"key":"B","text":"glass, Yuto"},{"key":"C","text":"glass. Yuto"},{"key":"D","text":"glass: Yuto"}]$lyceon_json$::jsonb, 'A', NULL, E'The sentence presents a colon-introduced list of three items, each of which contains internal commas (for example, the appositive describing each sculpture). When list items contain their own commas, semicolons must be used to separate the items so that readers can distinguish item boundaries from internal punctuation. Using a comma to separate items in a list that already contains commas creates ambiguity about where one item ends and the next begins. Placing a period after "glass" breaks the colon-introduced list into a new sentence; "Yuto Kobayashi''s ''Salt Meridian,'' a rotating assemblage..." would lack a main verb and constitute a fragment. Introducing a second colon after the first one is non-standard in English—a colon introduces a single list or explanation, and nesting another colon within that structure violates standard punctuation conventions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW25X1HS1', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 3, 'mcq', E'Which choice best describes the function of the second paragraph in relation to the first?', E'Geochemist Clair Patterson spent years developing an ultra-precise method for measuring lead isotopes in meteorite samples. By 1956, his calculations had yielded an age for the Earth of 4.55 billion years — a figure that has remained essentially unchanged by subsequent research and is still accepted today.
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW275APRP', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 2, 'mcq', E'Which quotation from a literary critic, if accurate, would most effectively support the claim presented in the text?', E'Some scholars of postcolonial literature argue that Ngũgĩ wa Thiong''o''s decision to write his later novels in Gĩkũyũ rather than English was not merely a political gesture but a substantive literary choice that altered the narrative textures of his fiction. These scholars contend that the Gĩkũyũ language''s oral storytelling conventions — including its characteristic use of repetition, call-and-response patterns, and communal narrative voice — became structural elements of the novels themselves, producing a fundamentally different reading experience than his earlier English-language works.', $lyceon_json$[{"key":"A","text":"\"Ngũgĩ's shift to Gĩkũyũ limited his international readership, which ultimately diminished the political impact he had hoped to achieve through linguistic decolonization.\""},{"key":"B","text":"\"In Matigari, the recursive phrasing and collective narrator that permeate the Gĩkũyũ text are not ornamental; they enact the oral performance tradition in prose form, generating rhythms absent from Ngũgĩ's earlier novels like Petals of Blood.\""},{"key":"C","text":"\"Ngũgĩ's English-language novels remain his most structurally innovative works, as the conventions of English prose allowed for greater experimentation with form.\""},{"key":"D","text":"\"The political content of Ngũgĩ's Gĩkũyũ novels is virtually identical to that of his English novels, suggesting that the language change was primarily symbolic.\""}]$lyceon_json$::jsonb, 'B', NULL, E'The claim is that writing in Gĩkũyũ altered the narrative textures of Ngũgĩ''s fiction by incorporating oral storytelling conventions as structural elements. The quotation about Matigari''s recursive phrasing and collective narrator enacting oral performance tradition directly supports this claim by identifying specific Gĩkũyũ oral conventions that became structural features absent from earlier English-language works. The quotation about diminished readership addresses political impact and audience size, not narrative texture. The quotation praising the English-language novels as more structurally innovative contradicts the claim rather than supporting it. The quotation characterizing the language change as primarily symbolic directly opposes the claim that the shift was a substantive literary choice affecting narrative structure.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW275RAE8', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 2, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'During the 1920s, archaeologist Gertrude Caton-Thompson challenged the prevailing European claim that the stone ruins of Great Zimbabwe must have been constructed by outside colonizers. Her meticulous excavations __________ the indigenous origin of the site, demonstrating through stratigraphic evidence that the Shona people had built the complex without external intervention.', $lyceon_json$[{"key":"A","text":"confirmed"},{"key":"B","text":"fabricated"},{"key":"C","text":"obscured"},{"key":"D","text":"predicted"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage states that Caton-Thompson used stratigraphic evidence to demonstrate the indigenous origin of the ruins, meaning her excavations provided proof supporting that conclusion. "Confirmed" means to establish the truth of something, which fits this evidentiary role. "Fabricated" means to invent or manufacture falsely, implying the origin was made up rather than proven — the opposite of what the passage describes. "Obscured" means to make unclear or hidden, which contradicts the passage''s emphasis on demonstrating a clear conclusion. "Predicted" means to forecast something before it happens, but the excavations were not forecasting; they were providing after-the-fact evidence.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW280CDXO', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 2, 'mcq', E'Which choice best states the main idea of the text?', E'Lichenometry, the technique of dating rock surfaces by measuring lichen growth, has long been used to estimate the ages of glacial moraines and rockfall deposits. However, lichenologist Asta Pellinen has argued that the method''s reliability diminishes sharply in maritime climates where fog and salt spray accelerate lichen growth rates unpredictably. Pellinen''s 2019 field study on the Lofoten archipelago found that growth rates of Rhizocarpon geographicum varied by as much as 370 percent between sites separated by fewer than eleven kilometers, a discrepancy she attributes to microclimatic differences in moisture exposure. Pellinen contends that without site-specific calibration curves, lichenometric dates in coastal regions may carry error margins large enough to undermine their geological usefulness.', $lyceon_json$[{"key":"A","text":"Rhizocarpon geographicum is the only lichen species suitable for lichenometric dating in maritime environments."},{"key":"B","text":"Lichenometry has been replaced by more accurate dating methods in most geological applications."},{"key":"C","text":"Research by Pellinen suggests that lichenometric dating is significantly less reliable in coastal areas due to variable lichen growth rates."},{"key":"D","text":"Pellinen's work demonstrates that lichen growth rates are primarily determined by the altitude of the rock surface being measured."}]$lyceon_json$::jsonb, 'C', NULL, E'The passage presents Pellinen''s argument that lichenometry becomes unreliable in maritime climates because fog and salt spray cause unpredictable variation in lichen growth rates, supported by her finding of 370 percent variation across nearby sites. The choice identifying Pellinen''s research as showing reduced reliability of lichenometric dating in coastal areas due to variable growth rates accurately captures this central idea. The claim that Rhizocarpon geographicum is the only suitable species misreads the passage, which mentions this species as one used in the study but makes no exclusivity claim. The suggestion that lichenometry has been replaced entirely goes well beyond the passage, which discusses limitations in one specific environment. The claim about altitude determining growth rates contradicts the passage, which attributes variation to microclimatic differences in moisture exposure, not altitude.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"detail_misread"},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"correct","error_taxonomy":null},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW28A261A', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 3, 'mcq', E'Which choice most logically completes the text?', E'Literary historian Tomoko Arai has examined the publication records of women novelists in Meiji-era Japan (1868–1912) and found that their output clustered heavily in two brief periods: 1887–1891 and 1907–1912. During the intervening years, very few novels by women were published despite a general expansion of the Japanese publishing industry. Arai notes that the first cluster coincides with the height of the Freedom and People''s Rights Movement, which championed women''s public participation, while the second cluster overlaps with the emergence of feminist literary journals such as Seitō. However, Arai cautions against a simple causal reading, observing that several prominent women novelists active during the first cluster — including Miyake Kaho and Wakamatsu Shizuko — did not cite political movements as motivating their work and instead described their entry into publishing as facilitated by personal connections to male editors. Arai therefore argues that ________', $lyceon_json$[{"key":"A","text":"the political movements of both periods were largely irrelevant to women's literary production, which was driven entirely by individual patronage networks."},{"key":"B","text":"the clustering pattern likely reflects the convergence of broad cultural openings created by political movements and the specific institutional access that personal networks provided to individual writers."},{"key":"C","text":"Miyake Kaho and Wakamatsu Shizuko were the only women novelists of the first cluster whose work achieved lasting literary significance."},{"key":"D","text":"feminist literary journals such as Seitō were modeled directly on publications from the Freedom and People's Rights Movement."}]$lyceon_json$::jsonb, 'B', NULL, E'Arai presents two types of evidence: the clustering aligns with political movements that expanded women''s public participation, but individual novelists attributed their publishing careers to personal editorial connections rather than political motivation. She cautions against a simple causal reading, implying that neither factor alone is sufficient. The logical completion is that both broad cultural openings from political movements and specific institutional access through personal networks contributed to the clustering pattern. The claim that political movements were largely irrelevant captures only Arai''s caveat about personal connections while ignoring the temporal correlation she identifies, representing incomplete reasoning. The claim about lasting literary significance of specific authors introduces an evaluative judgment absent from the passage. The suggestion that Seitō was modeled on earlier movement publications has no basis in the text, which merely notes temporal overlap between the journal and the second cluster.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29HBC08', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 3, 'mcq', E'Which choice completes the text with the most logical transition?', E'Archaeologists studying the Indus Valley civilization have noted that its cities, unlike contemporary Mesopotamian and Egyptian urban centers, lack monumental royal tombs or palatial complexes. Some scholars interpret this absence as evidence of a more egalitarian social structure. ______ other researchers point out that the uniformity of Indus brick sizes, standardized weights, and sophisticated drainage systems implies a powerful centralized authority — one whose legitimacy may simply not have been expressed through ostentatious architecture.', $lyceon_json$[{"key":"A","text":"By contrast,"},{"key":"B","text":"Consequently,"},{"key":"C","text":"Similarly,"},{"key":"D","text":"In other words,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage presents two competing scholarly interpretations: some scholars read the lack of monumental architecture as evidence of egalitarianism, while others argue that standardized infrastructure actually implies centralized authority. "By contrast," correctly marks the shift from the first interpretation to the opposing one. "Consequently," implies the second interpretation follows logically from the first, but the two interpretations are in tension. "Similarly," suggests the second group agrees with the first, when they actually disagree about the significance of the evidence. "In other words," signals a restatement, but the second view introduces a fundamentally different conclusion rather than rephrasing the first.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW29YLR6W', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 3, 'mcq', E'Which choice best characterizes the relationship between the two texts?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2AM73LF', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The committee will award the Hargrove Fellowship to the candidate ______ the review panel determines has demonstrated the most innovative approach to addressing groundwater contamination in arid agricultural regions.', $lyceon_json$[{"key":"A","text":"whom"},{"key":"B","text":"who"},{"key":"C","text":"which"},{"key":"D","text":"whoever"}]$lyceon_json$::jsonb, 'B', NULL, E'The relative pronoun must serve as the subject of "has demonstrated" in the clause "[who/whom] has demonstrated the most innovative approach." The intervening phrase "the review panel determines" is a parenthetical interpolation and does not change the grammatical role of the pronoun. Because the pronoun functions as the subject of "has demonstrated," the subjective case "who" is required. "Whom" is the objective case and would be appropriate only if the pronoun were the object of a verb or preposition; students who select it may mistakenly treat the pronoun as the object of "determines." "Which" is used for non-human antecedents and cannot refer to a person. "Whoever" is a generalized relative pronoun inappropriate in this context because the sentence specifies a definite antecedent ("the candidate"), and "the candidate whoever" produces a grammatically awkward construction.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2B7LQ5A', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The restoration plan requires that the wetland''s natural hydrology be reestablished, that nonnative species currently dominating the understory ______ and that a monitoring protocol documenting changes in species diversity be implemented within the first two years of the project.', $lyceon_json$[{"key":"A","text":"be removed,"},{"key":"B","text":"are removed,"},{"key":"C","text":"will be removed,"},{"key":"D","text":"have been removed,"}]$lyceon_json$::jsonb, 'A', NULL, E'The verb "requires" triggers the mandative subjunctive in each of the three parallel "that" clauses. The first clause uses "be reestablished" and the third uses "be implemented," both in the subjunctive base form. Parallel structure and the subjunctive mandate demand that the second clause also use the base form "be removed." The indicative "are removed" breaks the subjunctive pattern required by "requires that" and disrupts the parallel structure, even though it might sound natural with the plural subject "species." "Will be removed" introduces the future tense, which is incompatible with the mandative subjunctive construction; the subjunctive already conveys the sense of a requirement or command without marking future time. "Have been removed" uses the present perfect, implying a completed action, which contradicts the forward-looking nature of a restoration plan that requires future actions.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2BGEPRO', 'RW', 2, 'Standard English Conventions', ARRAY['Form, Structure, and Sense'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'Although the ceramic tradition known as Jōmon pottery originated over sixteen thousand years ago in the Japanese archipelago, contemporary archaeologists now ______ that the intricate cord-marked patterns adorning these vessels served not merely as decoration but as a sophisticated system for regulating heat distribution during cooking.', $lyceon_json$[{"key":"A","text":"believed"},{"key":"B","text":"believe"},{"key":"C","text":"are believing"},{"key":"D","text":"had believed"}]$lyceon_json$::jsonb, 'B', NULL, E'The adverb "now" signals that the sentence describes what archaeologists currently think, requiring the present tense "believe." The past tense "believed" incorrectly shifts the timeframe to the past despite the explicit present-time marker "now"; a student who selects it may have been influenced by the historical context of the passage but overlooked the temporal signal. "Are believing" misapplies the progressive aspect to the stative verb "believe," which in standard English describes a mental state rather than an ongoing action and does not take the progressive form. "Had believed" is the past perfect tense, used to describe an action completed before another past event, which conflicts with the present-time framing established by "now."', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"partial_reasoning"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EMSDSN', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 1, 'mcq', E'Based on the texts, how would the author of Text 2 most likely respond to the claim made in Text 1?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2EX5MXR', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 1, 'mcq', E'Which choice best describes the function of the underlined sentence in the text as a whole?', E'The fruit fly Drosophila melanogaster has been a staple of genetic research for over a century. Its genome was fully sequenced in the year 2000, revealing approximately 13,600 genes. _Many of these genes have direct counterparts in the human genome._ This genetic overlap is why findings from fruit fly studies frequently inform our understanding of human diseases such as Parkinson''s and Alzheimer''s.', $lyceon_json$[{"key":"A","text":"It establishes the connection that explains why fruit fly research is relevant to human medicine."},{"key":"B","text":"It provides a historical overview of how fruit fly research began."},{"key":"C","text":"It questions whether the fruit fly genome is sufficiently complex for research purposes."},{"key":"D","text":"It summarizes the total number of genes discovered in the fruit fly genome."}]$lyceon_json$::jsonb, 'A', NULL, E'The underlined sentence states that many fruit fly genes have direct counterparts in the human genome. The sentence that follows explains that this overlap is why fruit fly research informs understanding of human diseases. The underlined sentence therefore establishes the genetic link that makes fruit fly studies applicable to human medicine. The claim that it provides a historical overview is incorrect because the sentence discusses genetic similarity, not the history of the research. The suggestion that it questions the genome''s complexity is wrong because the sentence makes no evaluative claim about complexity. The idea that it summarizes the gene count is inaccurate because the gene count (13,600) appears in the preceding sentence, not the underlined one.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2FIE8LP', 'RW', 2, 'Craft and Structure', ARRAY['Cross-Text Connections'], 2, 'mcq', E'Which choice best describes a difference in how the two authors approach the topic of coral reef restoration?', E'Text 1
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2H18C1P', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 2, 'mcq', E'A student is writing an article for a local history journal and wants to present a contrast between two phases of the Salton Sea''s history. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2I9V08D', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 3, 'mcq', E'Which finding, if true, would most directly undermine the explanation proposed by Okafor''s team?', E'Entomologist Chinyere Okafor and her team have proposed that the rapid northward range expansion of the marbled stink bug (Halyomorpha variegata) in eastern North America is driven primarily by the insect''s physiological cold tolerance. Their laboratory assays showed that H. variegata adults can survive sustained exposure to temperatures as low as -17°C by entering a diapause state that lowers their supercooling point. Okafor''s team argues that this cold hardiness allows the species to overwinter successfully in regions previously assumed to be climatically inhospitable, accounting for the 430-kilometer northward shift in the species'' range boundary observed between 2014 and 2023.', $lyceon_json$[{"key":"A","text":"Field surveys reveal that H. variegata overwinters almost exclusively inside heated human structures such as barns and attics, rarely surviving in outdoor diapause even in regions where winter temperatures stay above -10°C."},{"key":"B","text":"A closely related species, H. meridionalis, has also expanded its range northward during the same period despite having a significantly higher supercooling point."},{"key":"C","text":"H. variegata populations in their original southern range have declined slightly over the past decade due to increased parasitoid pressure."},{"key":"D","text":"Climate records indicate that average winter low temperatures in the northeastern United States have risen by approximately 2.3°C since 2014."}]$lyceon_json$::jsonb, 'A', NULL, E'Okafor''s explanation holds that physiological cold tolerance — specifically diapause-mediated lowering of the supercooling point — enables outdoor overwintering in newly colonized northern regions. The finding that H. variegata almost exclusively overwinters inside heated structures and rarely survives outdoor diapause even above -10°C directly undermines this mechanism: if the insects depend on human shelter rather than their own cold hardiness, then physiological cold tolerance is not the driver of range expansion. The finding about a related species with a higher supercooling point also expanding northward is suggestive but does not directly address whether H. variegata''s own cold tolerance is the operative mechanism, since the related species may be expanding for different reasons. The finding about southern population declines due to parasitoids concerns a different phenomenon unrelated to the cold-tolerance explanation. The finding about rising winter temperatures could be seen as offering an alternative explanation, but it does not directly undermine the cold-tolerance mechanism — it simply suggests warming may also contribute — and Okafor could argue both factors operate simultaneously.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"partial_reasoning"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"partial_reasoning"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 105, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2JSPWFR', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 1, 'mcq', E'Which choice completes the text with the most logical transition?', E'Researchers at the University of Bergen have documented that certain species of Arctic mosses can photosynthesize even when buried under thin layers of snow. ______ these mosses are among the first organisms to resume growth each spring, often weeks before the snow fully melts.', $lyceon_json$[{"key":"A","text":"As a result,"},{"key":"B","text":"In contrast,"},{"key":"C","text":"For instance,"},{"key":"D","text":"On the other hand,"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage establishes that Arctic mosses can photosynthesize under snow, and the sentence after the blank describes a consequence of that ability — early spring growth. The cause-effect transition "As a result," correctly links the mosses'' under-snow photosynthesis to their early resumption of growth. "In contrast," and "On the other hand," both signal opposition, but the second sentence extends rather than contradicts the first. "For instance," signals an example, but the second sentence is a consequence of the first, not an illustration of it.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2LRYKAC', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 1, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Marine biologists studying the Mariana Trench have found that certain amphipods thrive at depths exceeding 10,000 meters. The ability of these organisms to __________ such extreme hydrostatic pressure has prompted researchers to investigate the molecular composition of their cell membranes.', $lyceon_json$[{"key":"A","text":"withstand"},{"key":"B","text":"circumvent"},{"key":"C","text":"generate"},{"key":"D","text":"broadcast"}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes organisms that survive and function under extreme hydrostatic pressure at great ocean depths. "Withstand" means to endure or resist something, which precisely fits the idea of surviving extreme pressure. "Circumvent" means to find a way around or avoid, but the organisms are not avoiding the pressure — they live directly within it. "Generate" means to produce or create, which reverses the relationship: the organisms are not creating the pressure. "Broadcast" means to transmit widely, which has no meaningful connection to enduring physical force.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"vocab_context_error"},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2N2Q8YJ', 'RW', 2, 'Expression of Ideas', ARRAY['Transitions'], 2, 'mcq', E'Which choice completes the text with the most logical transition?', E'During the 1970s, the Brazilian government encouraged large-scale cattle ranching in the Amazon basin by offering generous tax incentives to landowners who cleared forest. ______ many of the ranches established during this period proved economically unviable within a decade, as the nutrient-poor tropical soils could not sustain productive pastureland without costly inputs.', $lyceon_json$[{"key":"A","text":"Specifically,"},{"key":"B","text":"Nevertheless,"},{"key":"C","text":"Accordingly,"},{"key":"D","text":"Meanwhile,"}]$lyceon_json$::jsonb, 'B', NULL, E'The first sentence describes the government actively promoting ranching through incentives, which implies an expectation of success. The second sentence reveals that the ranches were economically unviable — an outcome that contradicts the expected result. "Nevertheless," correctly signals this concessive relationship. "Specifically," would introduce a clarifying detail, but the second sentence introduces a contrasting outcome, not a specification. "Accordingly," implies the failure logically followed from the incentives, reversing the intended causal logic. "Meanwhile," signals simultaneity rather than concession.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"inference_overreach"},"D":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2O5YPF3', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 2, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The cassowary, a large flightless bird native to the tropical forests of New Guinea and northeastern ______ plays a crucial ecological role by dispersing the seeds of more than two hundred and forty plant species through its digestive tract.', $lyceon_json$[{"key":"A","text":"Australia plays"},{"key":"B","text":"Australia, plays"},{"key":"C","text":"Australia. Plays"},{"key":"D","text":"Australia; plays"}]$lyceon_json$::jsonb, 'B', NULL, E'The phrase "a large flightless bird native to the tropical forests of New Guinea and northeastern Australia" is a nonrestrictive appositive renaming "The cassowary." Because the appositive is introduced by a comma after "cassowary," it must be closed with a matching comma before the main verb "plays." Omitting the closing comma fails to properly delimit the appositive, producing a structural error. Placing a period after "Australia" severs the subject from its predicate: "The cassowary, a large flightless bird...Australia." has no main verb, creating a fragment, while "Plays a crucial ecological role..." lacks a subject. A semicolon is incorrect because the subject with its appositive is not an independent clause—it has no predicate of its own.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2OKKNMW', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 1, 'mcq', E'A student is writing a brief introduction about glass frogs for a biology newsletter aimed at readers unfamiliar with the species. The student wants to emphasize what makes glass frogs visually distinctive. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2PQND19', 'RW', 2, 'Information and Ideas', ARRAY['Inferences'], 1, 'mcq', E'Which choice most logically completes the text?', E'Geochemist Yara Saldanha has been studying the mineral composition of volcanic ash deposits on the island of São Jorge in the Azores. Her analysis shows that ash layers from eruptions occurring between 1580 and 1808 contain unusually high concentrations of lithium-bearing phyllosilicates, minerals that form only when basaltic magma interacts extensively with seawater before erupting. Since São Jorge''s volcanic vents during this period were all located well inland, at elevations above 700 meters, Saldanha concludes that ________', $lyceon_json$[{"key":"A","text":"the lithium-bearing phyllosilicates were deposited on São Jorge by ocean currents rather than by volcanic eruptions."},{"key":"B","text":"significant quantities of seawater must have infiltrated the island's subsurface magma chambers despite the vents' inland and elevated positions."},{"key":"C","text":"São Jorge's volcanic eruptions between 1580 and 1808 were less explosive than eruptions during other periods."},{"key":"D","text":"lithium-bearing phyllosilicates can form without the interaction of magma and seawater under certain temperature conditions."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage establishes two facts: the ash contains minerals that form only from magma-seawater interaction, and the vents were inland at high elevation. The logical conclusion bridging these facts is that seawater must have infiltrated the subsurface magma chambers despite their inland location. The claim that ocean currents deposited the minerals contradicts the passage''s framing, which attributes the minerals to volcanic ash from eruptions. The suggestion about reduced explosiveness has no connection to the mineral composition evidence presented. The claim that these minerals can form without seawater contradicts the passage''s explicit statement that they form only when magma interacts extensively with seawater.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2Q9TQDU', 'RW', 2, 'Craft and Structure', ARRAY['Words in Context'], 3, 'mcq', E'Which choice completes the text with the most logical and precise word or phrase?', E'Literary critic Namwali Serpell has argued that Zambian novelist Binwell Sinyangwe''s prose achieves its emotional force not through explicit sentiment but through a technique of deliberate restraint. By leaving the interior states of his characters largely unnarrated, Sinyangwe __________ the reader''s interpretive involvement, compelling audiences to construct the emotional landscape from behavioral cues and environmental detail rather than from authorial declaration.', $lyceon_json$[{"key":"A","text":"curtails"},{"key":"B","text":"elicits"},{"key":"C","text":"displaces"},{"key":"D","text":"rehearses"}]$lyceon_json$::jsonb, 'B', NULL, E'The passage describes how Sinyangwe''s restraint compels readers to actively construct emotional meaning — his technique draws out or brings forth the reader''s interpretive participation. "Elicits" means to draw out or evoke a response, which precisely captures how the author''s restraint prompts active reader engagement. "Curtails" means to reduce or cut short, but the passage indicates the reader''s involvement is increased, not diminished. "Displaces" means to move something from its usual position or replace it, which does not capture the idea of drawing forth participation. "Rehearses" means to practice or repeat in preparation, which describes repetitive preparation rather than the act of evoking engagement.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"vocab_context_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"vocab_context_error"},"D":{"role":"distractor","error_taxonomy":"vocab_context_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R1M1DV', 'RW', 2, 'Information and Ideas', ARRAY['Command of Evidence'], 1, 'mcq', E'Which finding, if true, would most directly support the researchers'' hypothesis?', E'Marine biologists studying the decline of staghorn coral populations along the Belizean barrier reef have hypothesized that increased nighttime artificial light from coastal development disrupts the coral''s annual spawning synchrony. Staghorn corals rely on moonlight cues to coordinate mass spawning events, and the researchers propose that light pollution interferes with the corals'' ability to detect lunar cycles, causing fragmented spawning that reduces fertilization success.', $lyceon_json$[{"key":"A","text":"Staghorn coral populations near brightly lit resort developments spawn over a scattered 19-day window, while populations near undeveloped coastline spawn within a concentrated 3-day period."},{"key":"B","text":"Staghorn corals in the Belizean barrier reef grow at slower rates than staghorn corals in the Great Barrier Reef."},{"key":"C","text":"Coastal development in Belize has increased water temperatures by an average of 1.7 degrees Celsius over the past decade."},{"key":"D","text":"Staghorn corals are more genetically diverse in areas with higher human population density."}]$lyceon_json$::jsonb, 'A', NULL, E'The hypothesis claims that artificial light disrupts spawning synchrony by interfering with lunar cycle detection. The finding that corals near lit developments spawn over a scattered 19-day window while those near undeveloped coastline spawn within 3 days directly supports the proposed link between light pollution and fragmented spawning. The finding about slower growth rates in Belize compared to the Great Barrier Reef addresses growth rather than spawning synchrony and involves a different geographic comparison. The finding about increased water temperatures identifies a different environmental stressor unrelated to light pollution. The finding about genetic diversity near populated areas does not address spawning timing or light interference.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"C":{"role":"distractor","error_taxonomy":"evidence_mismatch"},"D":{"role":"distractor","error_taxonomy":"evidence_mismatch"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2R20RNK', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 3, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'The Chicxulub impactor — a bolide estimated at roughly eleven kilometers in diameter that struck the Yucatán Peninsula sixty-six million years ______ released energy equivalent to approximately ten billion nuclear detonations and ejected enough debris into the stratosphere to block sunlight for nearly two years.', $lyceon_json$[{"key":"A","text":"ago, released"},{"key":"B","text":"ago — released"},{"key":"C","text":"ago; released"},{"key":"D","text":"ago. It released"}]$lyceon_json$::jsonb, 'B', NULL, E'The parenthetical "a bolide estimated at roughly eleven kilometers in diameter that struck the Yucatán Peninsula sixty-six million years ago" is introduced by an em-dash after "impactor." In standard English, a parenthetical opened with an em-dash must be closed with a matching em-dash before the sentence resumes. Using a comma to close a dash-opened parenthetical mixes incompatible punctuation marks, violating the convention that paired delimiters must match. A semicolon is incorrect because the material preceding it—a subject ("The Chicxulub impactor") interrupted by a parenthetical—does not constitute an independent clause with its own predicate. Placing a period after "ago" and beginning a new sentence with "It released" severs the subject from its predicate, leaving "The Chicxulub impactor — a bolide...ago." as a fragment with no main verb.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"grammar_rule_error"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"sentence_boundary_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 120, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2SIRAJ3', 'RW', 2, 'Standard English Conventions', ARRAY['Boundaries'], 1, 'mcq', E'Which choice completes the text so that it conforms to the conventions of Standard English?', E'While cataloging over nine hundred beetle specimens collected from cloud forests in the Chiriquí Highlands of western ______ entomologist Annette Aiello discovered that thirty-seven of the species had never been formally described in any scientific publication.', $lyceon_json$[{"key":"A","text":"Panama, entomologist"},{"key":"B","text":"Panama. Entomologist"},{"key":"C","text":"Panama; entomologist"},{"key":"D","text":"Panama entomologist"}]$lyceon_json$::jsonb, 'A', NULL, E'The clause beginning with "While cataloging" is a dependent adverbial clause introduced by the subordinating conjunction "While." A comma is needed to separate this introductory dependent clause from the main clause beginning with "entomologist Annette Aiello discovered." Placing a period after "Panama" creates a sentence fragment because a dependent clause introduced by "While" cannot stand alone as a complete sentence. A semicolon is incorrect because semicolons join two independent clauses, and the "While" clause is dependent, not independent. Omitting punctuation entirely produces a run-on in which the dependent clause merges into the main clause without the required separation.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"C":{"role":"distractor","error_taxonomy":"sentence_boundary_error"},"D":{"role":"distractor","error_taxonomy":"grammar_rule_error"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2UZ160Q', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 3, 'mcq', E'Which choice best states the main idea of the text?', E'The philosopher Kwame Gyekye challenged the widespread characterization of African ethical thought as purely communitarian by distinguishing between what he called radical communitarianism and moderate communitarianism. Radical communitarianism, Gyekye argued, subordinates individual rights entirely to communal obligations, leaving no space for personal autonomy. While acknowledging that African societies do prize communal bonds, Gyekye maintained that many indigenous ethical frameworks also recognize individual moral agency and the capacity for independent judgment. His moderate communitarianism thus holds that the community and the individual are co-fundamental: neither is ontologically prior, and healthy social life requires balancing collective responsibility with respect for personal autonomy. Gyekye''s framework has been contested by scholars such as Ifeanyi Menkiti, who insists that personhood in African thought is constituted by communal incorporation and cannot be meaningfully separated from it.', $lyceon_json$[{"key":"A","text":"Gyekye proposed a moderate communitarianism that recognizes both communal bonds and individual moral agency as essential to African ethical thought, though this view has faced opposition."},{"key":"B","text":"Gyekye and Menkiti ultimately agree that African ethical systems are communitarian but disagree about whether Western ethical categories can adequately describe them."},{"key":"C","text":"Gyekye rejected communitarianism entirely and argued that African ethical thought is fundamentally individualistic in nature."},{"key":"D","text":"Gyekye's primary contribution was demonstrating that radical communitarianism is the dominant ethical framework across all African societies."}]$lyceon_json$::jsonb, 'A', NULL, E'The passage describes Gyekye''s distinction between radical and moderate communitarianism, emphasizing his view that community and individual are co-fundamental in African ethics, while noting Menkiti''s opposition to this framework. The choice stating that Gyekye proposed a moderate communitarianism recognizing both communal bonds and individual moral agency, with opposition from others, accurately captures the full scope of the passage. The claim that Gyekye and Menkiti agree on communitarianism but disagree about Western categories overreaches, since the passage shows them disagreeing about the fundamental role of the individual, not about Western descriptive categories. The suggestion that Gyekye rejected communitarianism entirely misreads the text: he challenged only radical communitarianism and explicitly proposed moderate communitarianism as an alternative. The claim that Gyekye demonstrated radical communitarianism as dominant contradicts the passage, in which Gyekye argues against radical communitarianism.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"inference_overreach"},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 90, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2VZCD3Y', 'RW', 2, 'Craft and Structure', ARRAY['Text Structure and Purpose'], 2, 'mcq', E'Which choice best describes the overall structure of the text?', E'In 1847, physician Ignaz Semmelweis noticed that the mortality rate from puerperal fever in a Vienna maternity ward staffed by medical students was three times higher than in a ward staffed by midwives. He hypothesized that the students were transferring "cadaverous particles" from autopsies to patients. When Semmelweis mandated handwashing with a chlorinated lime solution, the mortality rate dropped from 18 percent to under 2 percent. Despite this dramatic result, the medical establishment largely rejected his findings, and Semmelweis died in an asylum in 1865, his contribution unrecognized until decades later.', $lyceon_json$[{"key":"A","text":"It presents an observation, describes the response it prompted, and then details the reception of that response."},{"key":"B","text":"It introduces two competing medical theories and evaluates which one proved more accurate."},{"key":"C","text":"It describes a medical procedure and then lists the specific steps required to carry it out."},{"key":"D","text":"It provides a biography of a physician organized in order of professional achievements."}]$lyceon_json$::jsonb, 'A', NULL, E'The text follows a three-part structure: Semmelweis observed a mortality disparity (observation), he hypothesized a cause and introduced handwashing which reduced deaths (response), and the medical establishment rejected his findings (reception). The claim that it introduces two competing theories is wrong because only Semmelweis''s hypothesis is presented; no rival theory is described. The suggestion that it lists procedural steps is inaccurate because the passage narrates events rather than outlining a how-to process. The characterization as a biography organized by achievements misrepresents the passage, which focuses on a single discovery and its rejection rather than cataloging career milestones.', $lyceon_json${"A":{"role":"correct","error_taxonomy":null},"B":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"C":{"role":"distractor","error_taxonomy":"rhetorical_purpose_error"},"D":{"role":"distractor","error_taxonomy":"detail_misread"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 75, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2WZ6MML', 'RW', 2, 'Information and Ideas', ARRAY['Central Ideas and Details'], 1, 'mcq', E'Which choice best states the main idea of the text?', E'Recent archaeological work at the Sungir burial site in central Russia has revealed that Upper Paleolithic communities invested extraordinary labor in adorning the dead. Two juveniles buried approximately 34,000 years ago were found with over 10,000 mammoth-ivory beads, each of which researchers estimate took roughly 45 minutes to carve. The sheer quantity of ornamentation suggests that these communities devoted thousands of hours to funerary preparation, indicating that elaborate burial practices were already a significant social institution among early modern humans.', $lyceon_json$[{"key":"A","text":"Archaeologists have determined that mammoth-ivory beads were the primary form of currency in Upper Paleolithic Russia."},{"key":"B","text":"Findings at the Sungir burial site indicate that early modern humans dedicated substantial effort to funerary rituals."},{"key":"C","text":"The Sungir burial site is the oldest known archaeological site in central Russia."},{"key":"D","text":"Upper Paleolithic communities preferred to bury juveniles with more elaborate ornamentation than adults."}]$lyceon_json$::jsonb, 'B', NULL, E'The passage centers on the discovery that early modern humans at Sungir invested thousands of hours in preparing burial adornments, pointing to elaborate funerary practices as a significant social institution. The choice stating that findings indicate early modern humans dedicated substantial effort to funerary rituals captures this central idea. The claim about mammoth-ivory beads serving as currency goes beyond anything stated in the text, which discusses beads only as burial ornamentation. The claim about Sungir being the oldest site in central Russia misreads the passage, which provides a date but makes no comparative age claim. The suggestion that juveniles received more elaborate ornamentation than adults is unsupported, since the passage describes only the juvenile burial without comparing it to adult burials.', $lyceon_json${"A":{"role":"distractor","error_taxonomy":"inference_overreach"},"B":{"role":"correct","error_taxonomy":null},"C":{"role":"distractor","error_taxonomy":"detail_misread"},"D":{"role":"distractor","error_taxonomy":"inference_overreach"}}$lyceon_json$::jsonb, NULL, 'draft', 1, 60, false, $lyceon_json${"provenance":"Lyceon original","authored_by":"claude","authored_date":"2026-08-27"}$lyceon_json$::jsonb, $lyceon_json${"model":"claude","generation_date":"2026-08-27","prompt_version":"questions_governance_v1"}$lyceon_json$::jsonb);
INSERT INTO questions (id, section, source_type, domain, skill_codes, difficulty, item_type, stem, passage, options, correct_answer, correct_variants, explanation, option_metadata, assets, status, version, estimated_time_seconds, premium_flag, source_lineage, generation_attribution) VALUES ('SATRW2XNPJ9G', 'RW', 2, 'Expression of Ideas', ARRAY['Rhetorical Synthesis'], 3, 'mcq', E'A student is writing a research summary for an academic conference poster and wants to qualify a widely held assumption by presenting evidence that complicates it. Which choice most effectively uses the relevant information from the notes to accomplish this goal?
